// @ts-nocheck (reads files and runs the Python tools with node, as datatext.test.ts does; the engine tsconfig has no node types)
// The engine's catalogue and its self-check (docs/ENGINE-HOOKS.md, generated by tools/engine_catalog.py; tools/built_from.py).
//   1. The catalogue lists every trigger, predicate and op that effects/triggers.ts declares: the same names, the same counts.
//   2. built_from.py flags a name a spec invented, fails a spec with no Built-from table, flags a `case '<item id>'` handler
//      in a diff, and fails a diff that rolls a raw d20 (a lint fails on that too).
import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { join } from 'node:path';
import { TRIGGERS, PREDICATES, OPS } from '../src/effects/triggers';

const ROOT = join(__dirname, '..', '..', '..');
const FIX = join(ROOT, 'packages', 'engine', 'test', 'fixtures', 'built-from');
const tool = (...args: string[]) => spawnSync('python3', [join(ROOT, 'tools', 'built_from.py'), ...args], { encoding: 'utf8', cwd: ROOT, maxBuffer: 16 << 20 });

/** The first column of the table under a `### <title> (n)` heading of the catalogue, and the n it states. */
function listed(md: string, title: string): { n: number; names: string[] } {
  const at = md.indexOf('### ' + title + ' ('); expect(at, title + ' heading').toBeGreaterThan(-1);
  const n = Number(/\((\d+)\)/.exec(md.slice(at, at + 200))![1]);
  const rest = md.slice(at).split('\n').slice(1), names: string[] = [];
  let inTable = false;
  for (const l of rest) {
    if (l.startsWith('|')) { inTable = true; const m = /^\| `([^`]+)` \|/.exec(l); if (m) names.push(m[1]); continue; }
    if (inTable) break;
  }
  return { n, names };
}

describe('docs/ENGINE-HOOKS.md: the catalogue', () => {
  const md = readFileSync(join(ROOT, 'docs', 'ENGINE-HOOKS.md'), 'utf8');
  it('lists every trigger, predicate and op that effects/triggers.ts declares', () => {
    for (const [title, table] of [['Triggers', TRIGGERS], ['Predicates', PREDICATES], ['Ops', OPS]] as const) {
      const { n, names } = listed(md, title);
      expect(n, title + ' count').toBe(Object.keys(table).length);
      expect(names.length, title + ' rows').toBe(Object.keys(table).length);
      expect([...names].sort(), title).toEqual(Object.keys(table).sort());
    }
  });
});

describe('tools/built_from.py: the self-check', () => {
  it('a spec: reports a name it invented, and not the names the catalogue has', () => {
    const r = tool(join(FIX, 'spec-invented.md'));
    expect(r.status, r.stderr).toBe(0);
    const unknown = r.stdout.split('Unknown')[1] || '';
    expect(unknown).toContain('`frobnicate_hook`');
    for (const known of ['runTriggered', 'whyNot', 'turn_end', 'self_has', 'wake_word']) expect(unknown, known).not.toContain('`' + known + '`');
  });
  it('a spec with no Built-from table fails', () => {
    const r = tool(join(FIX, 'spec-no-table.md'));
    expect(r.status).toBe(1);
    expect(r.stdout).toContain('no table');
  });
  it('a diff: flags a `case \'some_item\'` handler and a new lane file, with what to use instead (advisory)', () => {
    const r = tool('--diff-file', join(FIX, 'handler.diff'));
    expect(r.status, r.stdout + r.stderr).toBe(0);
    expect(r.stdout).toMatch(/packages\/engine\/src\/perks\/x\.ts:4: smell: an item tested by its id in code/);
    expect(r.stdout).toMatch(/perks\/x\.ts:1: smell: a new lane file/);
    expect(r.stdout).toContain('`runTriggered` (effects/triggers.ts)');
  });
  it('a diff that a lint fails on (a raw d20) fails here too', () => {
    const r = tool('--diff-file', join(FIX, 'raw-roll.diff'));
    expect(r.status).toBe(1);
    expect(r.stdout).toMatch(/tactics\.ts:11: FAIL: a d20 rolled outside rolls\.ts/);
    expect(r.stdout).toContain('`rollVs` (rolls.ts)');
  });
});
